/* ==========================================================================
   全局变量定义区 (三大模块）
   ========================================================================== */
:root {
  /* ── 全局主背景色 (消息区与底部打底完全贯通❎用壁纸删这里) ── */
  --c-main-bg: #fcfdff;                             /* 固定背景基底色：清透霜白 */

  /* ── 模块 1：顶部导航色彩与配置 ── */
  --header-bg: rgba(244, 245, 247, 0.94);            /* 顶部背景：温润透亮冷灰 (#F4F5F7) */
  --header-blur: 20px;                              /* 背景毛玻璃模糊度 */
  --header-border-bottom: 1px solid rgba(0, 0, 0, 0.07); /* 顶部底部分割线 */
  --header-total-height: 110px;                     /* 顶部容器总高度 ❎顶部被压缩优先改大这里*/
  --header-text-main: #52575f;                      /* 标题、返回键核心文字颜色 (柔和炭灰) */
  --header-text-sub: #9ea4ad;                       /* 未选中标签弱化颜色 (冷浅灰) */
  --tab-font-size: 13.5px;                          /* 标签字号 */
  --tab-color-active: #484d55;                      /* Nearby 选中颜色 */
  --tab-color-inactive: #9ea4ad;                    /* 标签未选中颜色 */
  --tab-indicator-color: #9298a2;                   /* 底部高光条颜色 */
  --tab-offset-left: 45px;                          /* 标签左偏移 */
  --header-avatar-size: 48px;                       /* 右侧大头像尺寸 */
  --header-avatar-img: url('https://imgbed.heliar.top/i/bL8aKGFd5LRK9SQW_IMG_3862.jpeg');
  --header-avatar-border: 1px solid rgba(0, 0, 0, 0.08); /* 头像轮廓细线 */

  /* ── 模块 2：底部输入区域色彩与配置 ── */
  --custom-input-bg: #fcfdff;              /* 底栏最外层背景：完全同步消息区大底色 (#FCFDFF) */
  --custom-safe-bottom: calc(18px + var(--nuo-safe-bottom, 0px)); /* 底部安全间距 */
  --custom-card-bg: #f4f5f7;                        /* 输入卡片本体底色：与顶部呼应的浅冷灰 */
  --custom-card-radius: 6px;                        /* 输入卡片圆角 */
  --custom-card-height: 42px;                       /* 输入卡片高度 */
  --custom-plus-color: #7b7e84;                     /* 加号图标：中性冷石灰 */
  --custom-input-text: #2c3038;                     /* 输入框文字：清晰冷墨灰 */
  --custom-placeholder-color: #9ea4ad;              /* 占位提示词 (message) 颜色 */
  --custom-sticker-icon-color: #7b7e84;             /* 右侧三杠图标：中性冷石灰 */
  --custom-action-box-size: 38px;                   /* 外置按钮尺寸 */
  --custom-action-border: #dce0e6;                  /* 外置按钮边框细线 */
  --custom-action-radius: 12px;                     /* 外置按钮圆角 */
  --custom-action-bg: var(--c-main-bg);             /* 发送键/动作键背景底色：融入大底 */
  --custom-action-icon-color: #7b7e84;              /* 外置按钮内部图标 (箭头/方块) 颜色 */

  /* ── 模块 3：聊天消息区域色彩与配置 ── */
  --msg-font-size: 12px;                            /* ❎❎气泡文字字号 */
  --msg-font-size-sub: 11px;                        /* 辅助/次要文字字号 */
  --msg-font-size-quote: 10.5px;                    /* 引用文字字号 */
  --msg-bubble-padding: 5px 8px;                    /* 气泡内边距 */
  --c-text-main: #2c3038;                           /* 正文字体：纯正冷墨灰，字迹清晰 */
  --c-text-muted: #6c727d;                          /* 翻译/引用副文字：细腻钢笔灰 */

  /* 我方气泡：指定微灰冷白 + 清透浅银描边 (彻底无阴影) */
  --c-me-bg: #ffffff;                               /* 我方气泡底色：细腻微灰白纸色 */
  --c-me-border: #d0d4db;                           /* 我方气泡描边：中性质感浅细线 */

  /* 对方气泡：两层极简纯净灰阶 (首条深锚定，后续全浅收拢，告别混乱与脏感) */

--c-ai-step-1: #ebedf2;        /* 首条：比后续只深一点点，干净冷灰 */
--c-ai-step-follow: #f2f4f7;   /* 后续：直接用你方气泡的颜色 */

  /* 辅助与杂项控制 */
  --translation-always-show: 1;
  --translation-btn-display: none;
  --voice-download-display: none;
  --nq-avatar-border: #e5e5e5;                     /* 头像内描边 */
}

/* ==========================================================================
   第一部分：顶部导航 (Header)
   ========================================================================== */

/* 顶部容器外层：只在聊天界面生效 */
.glass-header:has(.header-profile-section) {
  background: var(--header-bg) !important;
  backdrop-filter: blur(var(--header-blur)) !important;
  -webkit-backdrop-filter: blur(var(--header-blur)) !important;
  border-bottom: var(--header-border-bottom) !important;
  box-shadow: none !important;
  height: var(--header-total-height) !important;
  position: relative !important;
  display: flex !important;
  align-items: flex-start !important;
  padding-top: calc(env(safe-area-inset-top, 44px) + 2px) !important; /*  整体上下位置：+2px 越大越往下，越小/负数越往上 */
  padding-left: 12px !important; /*  整体左右位置：12px 越大越往右 */
  padding-right: 14px !important; /*  整体右侧留白：14px */
  box-sizing: border-box !important;
}

/* 隐藏原生的聊天角色小头像 */
.glass-header:has(.header-profile-section) .header-avatar-container,
.glass-header:has(.header-profile-section) .chat-header-avatar {
  display: none !important;
}

/* 返回按钮：换用自定义矢量 Mask 图标 */
.glass-header:has(.header-profile-section) .header-btn-back {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;
  transform: translate(8px, 2px) !important; /* ❎ 返回键位置：第一个数8px=左右(越大越右)，第二个数2px=上下(越大越下，负数往上) */
  cursor: pointer !important;
}

/* 隐藏返回键自带的 SVG */
.glass-header:has(.header-profile-section) .header-btn-back svg {
  display: none !important;
}

/* 载入细线条冷灰返回键箭头 */
.glass-header:has(.header-profile-section) .header-btn-back::before {
  content: "" !important;
  display: block !important;
  width: 22px !important;
  height: 22px !important;
  background-color: var(--header-text-main) !important;
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-position: center;
  -webkit-mask-size: contain;
  mask-size: contain;
  -webkit-mask-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23000' stroke-width='2.2' stroke-linecap='round' stroke-linejoin='round'><path d='M15 18l-6-6 6-6'/></svg>");
  mask-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23000' stroke-width='2.2' stroke-linecap='round' stroke-linejoin='round'><path d='M15 18l-6-6 6-6'/></svg>");
}

/* 标题部分 */
.glass-header:has(.header-profile-section) .header-profile-section {
  display: flex !important;
  align-items: center !important;
  margin-left: 8px !important; /* ❎ 标题距离返回键的左边距：8px 越大越往右 */
  transform: translateY(2px) !important; /* ❎ 标题上下位置：2px 越大越往下，负数越往上 */
}

.glass-header:has(.header-profile-section) .chat-header-title {
  color: var(--header-text-main) !important;
  -webkit-text-fill-color: var(--header-text-main) !important;
  font-size: 16.5px !important;
  font-weight: 600 !important;
  letter-spacing: -0.2px !important;
}

/* 隐藏副标题 */
.glass-header:has(.header-profile-section) .chat-header-subtitle {
  display: none !important;
}

/* 装饰区域：三段式标签 */
.glass-header:has(.header-profile-section)::after {
  content: "Nearby       Following       Explore";
  position: absolute !important;
  left: var(--tab-offset-left) !important; /* ❎ 标签栏左偏移，在全局变量里控制（当前45px） */
  bottom: 0px !important; /* ❎ 标签栏底部位置：0px 越大越往上 */
  height: 28px !important;
  line-height: 20px !important;
  font-size: var(--tab-font-size) !important;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif !important;
  font-style: normal !important;
  font-weight: 500 !important;
  letter-spacing: 0.3px !important;
  white-space: pre !important;
  pointer-events: none !important;
  color: var(--tab-color-inactive) !important;
  background-image: 
    linear-gradient(var(--tab-indicator-color), var(--tab-indicator-color)),
    linear-gradient(var(--tab-color-active), var(--tab-color-active));
  background-size: 44px 2px, 46px 100% !important;
  background-position: 0 bottom, 0 top !important;
  background-repeat: no-repeat !important;
  -webkit-background-clip: border-box, text !important;
  background-clip: border-box, text !important;
}

/* 电话与视频按钮保留透明点击区 */
.glass-header:has(.header-profile-section) .header-btn-phone,
.glass-header:has(.header-profile-section) .header-btn-video {
  opacity: 0 !important;
  pointer-events: auto !important;
  margin-right: 6px !important; /* ❎ 电话/视频按钮右边距：6px */
  transform: translateY(2px) !important; /* ❎ 电话/视频按钮上下位置：2px */
}

/* 右侧大头像改造 */
#chat-detail-screen .header-btn-info {
  width: var(--header-avatar-size) !important;
  height: var(--header-avatar-size) !important;
  border-radius: 50% !important;
  clip-path: circle(50% at 50% 50%) !important;
  -webkit-clip-path: circle(50% at 50% 50%) !important;
  background-color: transparent !important;
  background-image: var(--header-avatar-img) !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  box-shadow: none !important;
  border: none !important;
  outline: none !important;
  transform: translateY(0px) !important; /* ❎ 右侧大头像上下位置：0px 越大越往下，负数越往上 */
  flex-shrink: 0 !important;
  cursor: pointer !important;
}

/* 隐藏原本 info 键自带的图标 */
#chat-detail-screen .header-btn-info svg {
  display: none !important;
}

/* ==========================================================================
   第二部分：底部 (Footer)
   ========================================================================== */

/* 底栏外层大背景：与全局主背景色同步贯通 */
.input-area-custom,
div:has(> .input-row-wrapper) {
  background: var(--custom-input-bg) !important;
  border-top: none !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  padding-top: 8px !important;
  padding-left: 14px !important;
  padding-right: 66px !important;
  padding-bottom: var(--custom-safe-bottom) !important;
  box-sizing: border-box !important;
  position: relative !important;
}

/* F4F5F7 浅冷灰微方输入卡片本体 */
.input-row-wrapper {
  background: var(--custom-card-bg) !important;
  border: none !important;
  border-radius: var(--custom-card-radius) !important;
  height: var(--custom-card-height) !important;
  min-height: var(--custom-card-height) !important;
  display: flex !important;
  align-items: center !important;
  position: relative !important;
  width: 100% !important;
  box-sizing: border-box !important;
  overflow: visible !important;
  padding: 0 !important;
  gap: 0 !important;
}

/* 左侧加号按钮 */
.input-btn-plus {
  width: 38px !important;
  height: 100% !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  cursor: pointer !important;
  flex-shrink: 0 !important;
  margin: 0 !important;
  z-index: 5 !important;
}

.input-btn-plus svg {
  display: none !important;
}

.input-btn-plus::before {
  content: "" !important;
  display: block !important;
  width: 18px !important;
  height: 18px !important;
  background-color: var(--custom-plus-color) !important;
  -webkit-mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2.5' stroke-linecap='round' stroke-linejoin='round'><line x1='12' y1='5' x2='12' y2='19'/><line x1='5' y1='12' x2='19' y2='12'/></svg>") center/contain no-repeat !important;
  mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2.5' stroke-linecap='round' stroke-linejoin='round'><line x1='12' y1='5' x2='12' y2='19'/><line x1='5' y1='12' x2='19' y2='12'/></svg>") center/contain no-repeat !important;
}

/* 内部输入框容器 */
.input-action-bar-custom {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  height: 100% !important;
  min-height: 0 !important;
  padding: 0 8px 0 0 !important;
  margin: 0 !important;
  flex: 1 !important;
  display: flex !important;
  align-items: center !important;
  position: relative !important;
}

/* 输入框本体 */
#chat-message-input,
.input-box-custom {
  background: transparent !important;
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
  color: var(--custom-input-text) !important;
  -webkit-text-fill-color: var(--custom-input-text) !important;
  caret-color: var(--custom-input-text) !important;
  font-size: 15px !important;
  height: 100% !important;
  line-height: var(--custom-card-height) !important;
  padding: 0 !important;
  margin: 0 !important;
  width: 100% !important;
  position: relative !important;
  z-index: 2 !important;
}

/* 占位符修改为 "message" */
#chat-message-input::placeholder,
.input-box-custom::placeholder {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
}

.input-action-bar-custom:has(#chat-message-input:placeholder-shown)::before,
.input-action-bar-custom:has(.input-box-custom:placeholder-shown)::before {
  content: "Message" !important;
  position: absolute !important;
  left: 0 !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  color: var(--custom-placeholder-color) !important;
  font-size: 15px !important;
  pointer-events: none !important;
  z-index: 1 !important;
  letter-spacing: 0.3px !important;
}

/* 卡片内部右侧按钮组 */
.input-btns-right {
  display: flex !important;
  align-items: center !important;
  gap: 4px !important;
  padding: 0 !important;
  margin: 0 !important;
  z-index: 4 !important;
}

/* 语音按钮：透明隐形但保留热区 */
.input-btn-mic {
  opacity: 0 !important;
  pointer-events: auto !important;
  width: 24px !important;
  height: 28px !important;
  min-width: 24px !important;
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}

/* 表情替换为三杠 SVG */
.input-btn-sticker {
  width: 24px !important;
  height: 28px !important;
  min-width: 24px !important;
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  cursor: pointer !important;
  opacity: 1 !important;
}

.input-btn-sticker svg {
  display: none !important;
}

.input-btn-sticker::before {
  content: "" !important;
  display: block !important;
  width: 20px !important;
  height: 20px !important;
  background-color: var(--custom-sticker-icon-color) !important;
  -webkit-mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 48 48' fill='none'><path d='M7.94971 11.9497H39.9497' stroke='black' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'/><path d='M15.94971 23.9497H39.9497' stroke='black' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'/><path d='M23.94971 35.9497H39.9497' stroke='black' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'/></svg>") center/contain no-repeat !important;
  mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 48 48' fill='none'><path d='M7.94971 11.9497H39.9497' stroke='black' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'/><path d='M15.94971 23.9497H39.9497' stroke='black' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'/><path d='M23.94971 35.9497H39.9497' stroke='black' stroke-width='4' stroke-linecap='round' stroke-linejoin='round'/></svg>") center/contain no-repeat !important;
}

/* 独立外置动作按钮 (发送 / AI等待 / 停止生成，背景底色与大底无缝融合) */
.send-btn-custom,
.input-btn-ai,
.stop-btn-custom {
  position: absolute !important;
  right: -52px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  width: var(--custom-action-box-size) !important;
  height: var(--custom-action-box-size) !important;
  min-width: var(--custom-action-box-size) !important;
  min-height: var(--custom-action-box-size) !important;
  background: var(--custom-action-bg) !important;
  border: 1.5px solid var(--custom-action-border) !important;
  border-radius: var(--custom-action-radius) !important;
  box-shadow: none !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  padding: 0 !important;
  margin: 0 !important;
  cursor: pointer !important;
  z-index: 10 !important;
  transition: opacity 0.15s ease, transform 0.15s ease !important;
}

.send-btn-custom svg,
.input-btn-ai svg,
.stop-btn-custom svg {
  display: none !important;
}

/* 发送 / AI按键状态：折线箭头 > */
.send-btn-custom::before,
.input-btn-ai::before {
  content: "" !important;
  display: block !important;
  width: 14px !important;
  height: 14px !important;
  background-color: var(--custom-action-icon-color) !important;
  -webkit-mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2.5' stroke-linecap='round' stroke-linejoin='round'><polyline points='9 18 15 12 9 6'/></svg>") center/contain no-repeat !important;
  mask: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='black' stroke-width='2.5' stroke-linecap='round' stroke-linejoin='round'><polyline points='9 18 15 12 9 6'/></svg>") center/contain no-repeat !important;
}

/* 停止生成按键状态：小方块 ■ */
.stop-btn-custom::before {
  content: "" !important;
  display: block !important;
  width: 12px !important;
  height: 12px !important;
  background-color: var(--custom-action-icon-color) !important;
  border-radius: 2px !important;
}

/* 按压交互反馈 */
.send-btn-custom:active,
.input-btn-ai:active,
.stop-btn-custom:active,
.input-btn-sticker:active {
  transform: translateY(-50%) scale(0.92) !important;
  opacity: 0.65 !important;
}

/* ==========================================================================
   第三部分：聊天区域 (Chat Area)
   ========================================================================== */

/* 聊天区域主背景：牢固锁定大背景色，保证各层级对比稳定 */
.chat-messages-area,
.chat-messages-area[data-theme-style="qq"],
.chat-message-list-custom {
  background-color: var(--c-main-bg) !important;
}

/* 消息外层行容器间距 */
.msg-bubble-wrapper {
  margin-bottom: 6px !important;
  margin-top: 6px !important;
}

/* 连发紧凑，换人拉开 (全面覆盖 data 属性与原生分组类名) */
.msg-bubble-wrapper.is-mid,
.msg-bubble-wrapper.is-last,
.msg-bubble-wrapper:has(.mid),
.msg-bubble-wrapper:has(.last),
.msg-bubble-wrapper[data-first="false"] {
  margin-top: 2px !important;
}

.msg-bubble-wrapper.is-first,
.msg-bubble-wrapper.is-single,
.msg-bubble-wrapper:has(.first),
.msg-bubble-wrapper:has(.single),
.msg-bubble-wrapper[data-first="true"] {
  margin-top: 12px !important;
}

/* 头像外框与容器基础样式 ❎头像大小改下面的数值，当前36px */
.msg-avatar-them-container,
.msg-avatar-me-container {
  visibility: visible !important;
  display: flex !important;
}

.msg-avatar-them-inner,
.msg-avatar-me-inner,
.msg-avatar-custom,
.msg-them div[style*="width: 36px"][style*="border-radius"],
.msg-me div[style*="width: 36px"][style*="border-radius"] {
  width: 36px !important;
  height: 36px !important;
  border-radius: 30% !important;
  border: 1.5px solid var(--nq-avatar-border) !important;
  box-shadow: 0 0 0 2px #ffffff !important;
  box-sizing: border-box !important;
  overflow: hidden !important;
}

/* 气泡通用基准结构 (彻底去除阴影) */
.bubble-them-custom,
.bubble-me-custom {
  position: relative !important;
  overflow: visible !important;
  border-radius: 6px !important;
  padding: var(--msg-bubble-padding) !important;
  font-size: var(--msg-font-size) !important;
  line-height: 1.4 !important;
  box-sizing: border-box !important;
  transform: translateZ(0) !important;
  min-height: auto !important;
  box-shadow: none !important;
}

/* 对方气泡避让间距 */
.bubble-them-custom {
  margin-left: 2px !important;
}

/* ── 对方(AI/群友)气泡：绝对闭环两层逻辑架构 (首条深，后续全部浅，告别混乱与跳色) ── */

/* 1. 兜底与后续所有消息：统统锁定第二层【极浅雾银灰】#eff1f5，无论连发多少条绝不反弹 */
.bubble-them-custom,
.msg-them .bubble-them-custom,
[data-sender="them"] .bubble-them-custom {
  background: var(--c-ai-step-follow) !important;
  color: var(--c-text-main) !important;
  border: none !important;
}

/* 2. 第一层【沉稳深银灰】#dfe2e6：通过 data 属性、原生位置类、外层类名四重最高优先级锁死第一条与独发条 */
.bubble-them-custom.first,
.bubble-them-custom.single,
